  void showClientResults(String query,String category,String subject,boolean debtOnly){clear("نتیجه جستجوی موکلان","فیلتر اشخاص و پرونده‌های مرتبط");detailBack=this::casesHub;ArrayList<OfficeDb.ClientRecord> out=new ArrayList<>();String needle=query.trim();for(OfficeDb.ClientRecord c:db.clients()){String hay=c.name+" "+safe(c.phone)+" "+safe(c.nationalId);if(!blank(needle)&&!hay.contains(needle))continue;boolean match="همه".equals(category)&&"همه".equals(subject),debt=false;for(OfficeDb.CaseRecord x:db.cases(null,"همه",c.id)){if(("همه".equals(category)||category.equals(x.category))&&("همه".equals(subject)||subject.equals(x.subject)))match=true;if(db.summary(x).debt>0)debt=true;}if(match&&(!debtOnly||debt))out.add(c);}TextView pdf=action("خروجی PDF نتیجه ("+out.size()+" موکل)");pdf.setOnClickListener(v->preview("نتیجه جستجوی موکلان",clientsText(out)));page.addView(pdf);if(out.isEmpty())page.addView(empty("نتیجه‌ای پیدا نشد."));else for(OfficeDb.ClientRecord c:out)page.addView(clientCard(c));}
