  View taskCard(OfficeDb.TaskRecord t){LinearLayout card=row();card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(12),dp(11),dp(12),dp(11));card.setBackground(round(Color.WHITE,13));margin(card,0,0,0,8);CheckBox done=new CheckBox(this);done.setChecked(t.done==1);done.setOnCheckedChangeListener((b,c)->{db.setTaskDone(t.id,c);if(active==HOME)dayAgenda(t.date);else tasks();});card.addView(done);LinearLayout body=col();TextView h=txt(t.title,14,INK);h.setTypeface(null,Typeface.BOLD);body.addView(h);body.addView(txt(safe(t.date)+" · "+safe(t.time)+(blank(t.endTime)?"":" تا "+t.endTime)+" · "+safe(t.kind),10,MUTED));body.addView(txt("محل: "+safe(t.place)+" | "+safe(t.caseName),10,MUTED));if(!blank(t.notes))body.addView(txt(t.notes,10,MUTED));card.addView(body,weight());card.addView(badge(t.priority,"فوری".equals(t.priority)?RED:BLUE));card.setOnClickListener(v->showTaskDetail(t));return card;}

