  void selectClientReport(){List<OfficeDb.ClientRecord> list=db.clients();if(list.isEmpty()){toast("موکلی ثبت نشده است");return;}String[] names=new String[list.size()];for(int i=0;i<list.size();i++)names[i]=list.get(i).name;new AlertDialog.Builder(this).setTitle("انتخاب موکل").setItems(names,(d,n)->{OfficeDb.ClientRecord c=list.get(n);new AlertDialog.Builder(this).setTitle("گزارش "+c.name).setItems(new String[]{"صورت مالی","اقدامات و هزینه‌های وکیل"},(x,i)->preview(i==0?"صورت مالی "+c.name:"عملکرد "+c.name,i==0?db.clientFinancialText(c.id):db.performanceText(null,c.id))).show();}).show();}
  void reportCasesFilter(){LinearLayout f=form();Spinner status=spinner(new String[]{"همه پرونده‌ها","پرونده‌های جاری","پرونده‌های مختومه"}),cat=spinner(withAll(categoryList())),subject=spinner(withAll(subjectList()));for(View v:new View[]{status,cat,subject})f.addView(v);new AlertDialog.Builder(this).setTitle("فیلتر گزارش پرونده‌ها").setView(f).setNegativeButton("انصراف",null).setPositiveButton("پیش‌نمایش",(d,w)->{String st=status.getSelectedItemPosition()==1?"active":status.getSelectedItemPosition()==2?"closed":null;ArrayList<OfficeDb.CaseRecord> out=new ArrayList<>();for(OfficeDb.CaseRecord c:db.cases(st,cat.getSelectedItem().toString(),null))if("همه".equals(subject.getSelectedItem().toString())||subject.getSelectedItem().toString().equals(c.subject))out.add(c);preview("گزارش پرونده‌ها",casesText(out));}).show();}
  void reportClientsFilter(){LinearLayout f=form();Spinner cat=spinner(withAll(categoryList())),subject=spinner(withAll(subjectList())),debt=spinner(new String[]{"همه موکلان","فقط بدهکاران"});for(View v:new View[]{cat,subject,debt})f.addView(v);new AlertDialog.Builder(this).setTitle("فیلتر گزارش موکلان").setView(f).setNegativeButton("انصراف",null).setPositiveButton("پیش‌نمایش",(d,w)->{ArrayList<OfficeDb.ClientRecord> out=new ArrayList<>();for(OfficeDb.ClientRecord c:db.clients()){boolean match="همه".equals(cat.getSelectedItem().toString())&&"همه".equals(subject.getSelectedItem().toString()),hasDebt=false;for(OfficeDb.CaseRecord x:db.cases(null,"همه",c.id)){if(("همه".equals(cat.getSelectedItem().toString())||cat.getSelectedItem().toString().equals(x.category))&&("همه".equals(subject.getSelectedItem().toString())||subject.getSelectedItem().toString().equals(x.subject)))match=true;if(db.summary(x).debt>0)hasDebt=true;}if(match&&(debt.getSelectedItemPosition()==0||hasDebt))out.add(c);}preview("گزارش موکلان",clientsText(out));}).show();}
  void runReport(int type){String heading,body;if(type==0){heading="گزارش موکلان";StringBuilder b=new StringBuilder();for(OfficeDb.ClientRecord c:db.clients())b.append(c.name).append("\nتلفن: ").append(safe(c.phone)).append(" | کد ملی: ").append(safe(c.nationalId)).append("\nنشانی: ").append(safe(c.address)).append("\nپرونده‌ها: ").append(c.caseCount).append(" (جاری: ").append(c.activeCount).append(")\n\n");body=b.toString();}else if(type==6){heading="گزارش جامع مالی";StringBuilder b=new StringBuilder();for(OfficeDb.CaseRecord c:db.cases(null,"همه",null)){OfficeDb.AccountSummary a=db.summary(c);b.append(c.title).append(" | موکل: ").append(safe(c.clientName)).append("\nحق‌الوکاله: ").append(money(a.agreed)).append(" | دریافتی: ").append(money(a.received)).append("\nهزینه: ").append(money(a.expenses)).append(" | بدهی: ").append(money(a.debt)).append(" | بستانکاری: ").append(money(a.credit)).append("\nتوافق: ").append(safe(c.agreementNotes)).append("\n\n");}body=b.toString();}else{String status=type==1?"active":type==2?"closed":null,cat=type==3?"کیفری":type==4?"حقوقی":type==5?"خانواده":"همه";heading=type==1?"پرونده‌های جاری":type==2?"پرونده‌های مختومه":"پرونده‌های "+cat;StringBuilder b=new StringBuilder();for(OfficeDb.CaseRecord c:db.cases(status,cat,null))b.append(c.title).append("\nشماره: ").append(safe(c.caseNumber)).append(" | بایگانی: ").append(safe(c.archiveNumber)).append("\nموکل: ").append(safe(c.clientName)).append(" | دسته: ").append(safe(c.category)).append("\nموضوع: ").append(safe(c.subject)).append(" | شعبه: ").append(safe(c.branch)).append("\n\n");body=b.toString();}preview(heading,body);}
  void preview(String h,String body){ScrollView s=new ScrollView(this);TextView v=txt(body,13,INK);v.setPadding(dp(18),dp(14),dp(18),dp(14));v.setTextIsSelectable(true);s.addView(v);new AlertDialog.Builder(this).setTitle(h).setView(s).setNegativeButton("بستن",null).setPositiveButton("PDF / چاپ",(d,w)->print(h,html(h,body))).show();}

