  void lawyer(){clear("اطلاعات وکیل",prefs.getBoolean("profile_complete",false)?"مشخصات سربرگ و گزارش‌ها":"برای ورود، ابتدا مشخصات وکیل را ثبت کنید");LinearLayout images=row();ImageView photo=image(prefs.getString("photo",null)),logo=image(prefs.getString("logo",null));images.addView(photo,new LinearLayout.LayoutParams(0,dp(125),1));images.addView(logo,new LinearLayout.LayoutParams(0,dp(125),1));page.addView(images);LinearLayout choose=row();TextView p=action("انتخاب عکس وکیل"),l=action("انتخاب لوگوی کانون/مرکز");p.setOnClickListener(v->pickImage(PHOTO));l.setOnClickListener(v->pickImage(LOGO));choose.addView(p,weight());choose.addView(l,weight());page.addView(choose);EditText name=input("نام و نام خانوادگی *"),license=input("شماره پروانه وکالت"),center=input("کانون یا مرکز وکلا"),phone=input("شماره تلفن"),address=area("نشانی دفتر"),website=input("وب‌سایت");Spinner level=spinner(new String[]{"کارآموز وکالت","وکیل پایه دو دادگستری","وکیل پایه یک دادگستری"});name.setText(prefs.getString("name",""));license.setText(prefs.getString("license",""));center.setText(prefs.getString("center","کانون وکلای دادگستری مرکز"));phone.setText(prefs.getString("phone",""));address.setText(prefs.getString("address",""));website.setText(prefs.getString("website",""));level.setSelection(Math.max(0,Arrays.asList("کارآموز وکالت","وکیل پایه دو دادگستری","وکیل پایه یک دادگستری").indexOf(prefs.getString("lawyer_level","وکیل پایه یک دادگستری"))));for(View v:new View[]{name,level,license,center,phone,address,website})page.addView(v);TextView save=action("ذخیره اطلاعات و ورود");save.setOnClickListener(v->{if(blank(name.getText().toString())){name.setError("نام وکیل الزامی است");return;}prefs.edit().putString("name",name.getText().toString()).putString("lawyer_level",level.getSelectedItem().toString()).putString("license",license.getText().toString()).putString("center",center.getText().toString()).putString("phone",phone.getText().toString()).putString("address",address.getText().toString()).putString("website",website.getText().toString()).putBoolean("profile_complete",true).apply();toast("اطلاعات وکیل ذخیره شد");shell();dashboard();});page.addView(save);}
