  void backup(){clear("پشتیبان‌گیری امن","انتقال کنترل‌شده اطلاعات بین گوشی‌ها");page.addView(info("روش امن آفلاین","یک فایل رمزگذاری‌شده با پسوند .klo ساخته می‌شود. شما مقصد یا دریافت‌کننده را انتخاب می‌کنید و گوشی مقصد فقط با همان کد قادر به بازیابی است. کد را جداگانه منتقل کنید."));EditText code=input("کد بکاپ جدید حداقل ۱۲ کاراکتر؛ برای بازیابی کد فایل قبلی");code.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);TextView export=action("ساخت فایل پشتیبان رمزگذاری‌شده"),restore=action("بازیابی فایل پشتیبان در این گوشی");export.setOnClickListener(v->{if(code.length()<12){toast("برای بکاپ جدید، کد حداقل ۱۲ کاراکتر باشد");return;}pendingCode=code.getText().toString();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/octet-stream");i.putExtra(Intent.EXTRA_TITLE,"دفتر-وکالت-"+JalaliDate.today().value().replace('/','-')+".klo");startActivityForResult(i,EXPORT);});restore.setOnClickListener(v->{if(code.length()<6){toast("ابتدا کد فایل را وارد کنید");return;}pendingCode=code.getText().toString();new AlertDialog.Builder(this).setTitle("تأیید بازیابی").setMessage("اطلاعات فعلی با محتوای فایل جایگزین می‌شود. ادامه می‌دهید؟").setNegativeButton("خیر",null).setPositiveButton("ادامه",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);}).show();});page.addView(code);page.addView(export);page.addView(restore);}
  @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{if(req==PHOTO||req==LOGO){getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);prefs.edit().putString(req==PHOTO?"photo":"logo",uri.toString()).apply();lawyer();}else if(req==EXPORT){byte[] bytes=SecureBackup.encrypt(db.exportJson(),pendingCode);try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(bytes);}toast("پشتیبان رمزگذاری‌شده ذخیره شد");}else if(req==IMPORT){db.importJson(SecureBackup.decrypt(readAll(uri),pendingCode));ReminderReceiver.schedule(this);toast("اطلاعات بازیابی شد");go(HOME,false);}}catch(Exception e){new AlertDialog.Builder(this).setTitle("عملیات انجام نشد").setMessage("کد نادرست است یا فایل معتبر نیست.\n\n"+e.getClass().getSimpleName()).setPositiveButton("باشه",null).show();}finally{pendingCode=null;}}
  byte[] readAll(Uri uri)throws Exception{try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>25*1024*1024)throw new IllegalArgumentException("فایل پشتیبان بیش از ۲۵ مگابایت است");out.write(b,0,n);}return out.toByteArray();}}
  void settings(){clear("تنظیمات","دسترسی‌پذیری، امنیت و فهرست‌های قابل تنظیم");page.addView(info("نسخه برنامه","نسخه ۰٫۸٫۱ پیش‌نمایش — اطلاعات روی همین گوشی"));section("نمایش و دسترسی‌پذیری","اندازه نوشته‌ها و حالت روز یا شب");Spinner size=spinner(new String[]{"خیلی کوچک","کوچک","معمولی","بزرگ","خیلی بزرگ"});float[] scales={.85f,.95f,1f,1.15f,1.3f};int selected=Math.abs(fontScale-.85f)<.02?0:Math.abs(fontScale-.95f)<.02?1:Math.abs(fontScale-1.15f)<.02?3:Math.abs(fontScale-1.3f)<.02?4:2;size.setSelection(selected);page.addView(size);Switch night=new Switch(this);night.setText("حالت شب و زمینه تاریک");night.setTextColor(INK);night.setTextSize(14*fontScale);night.setChecked(dark);night.setPadding(dp(8),dp(12),dp(8),dp(12));page.addView(night);TextView appearance=action("اعمال تنظیمات نمایش");appearance.setOnClickListener(v->{prefs.edit().putFloat("font_scale",scales[size.getSelectedItemPosition()]).putBoolean("dark",night.isChecked()).apply();recreate();});page.addView(appearance);section("امنیت ورود","باز شدن برنامه با رمز اختصاصی وکیل");Switch lock=new Switch(this);lock.setText("درخواست رمز هنگام ورود");lock.setTextColor(INK);lock.setChecked(prefs.getBoolean("lock_enabled",false));EditText pass=input("رمز جدید، حداقل ۸ کاراکتر");pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);TextView savePass=action("ذخیره تنظیمات رمز");savePass.setOnClickListener(v->{if(lock.isChecked()&&pass.length()<8&&blank(prefs.getString("password_hash",""))){pass.setError("رمز حداقل ۸ کاراکتر لازم است");return;}SharedPreferences.Editor e=prefs.edit().putBoolean("lock_enabled",lock.isChecked());if(pass.length()>=8)e.putString("password_hash",strongHash(pass.getText().toString()));else if(pass.length()>0){pass.setError("رمز جدید باید حداقل ۸ کاراکتر باشد");return;}if(!lock.isChecked())e.putBoolean("biometric_enabled",false);e.apply();authenticated=lock.isChecked();toast("تنظیمات رمز ذخیره شد");});page.addView(lock);page.addView(pass);page.addView(savePass);Switch biom=new Switch(this);biom.setText("باز کردن با اثر انگشت، پس از فعال‌سازی رمز (اندروید ۹ به بالا)");biom.setTextColor(INK);biom.setChecked(prefs.getBoolean("biometric_enabled",false));biom.setOnCheckedChangeListener((button,checked)->{if(checked&&!prefs.getBoolean("lock_enabled",false)){biom.setChecked(false);toast("ابتدا رمز برنامه را فعال کنید");return;}prefs.edit().putBoolean("biometric_enabled",checked).apply();});page.addView(biom);section("یادآوری مهلت‌ها","اعلان‌های چندمرحله‌ای؛ زمان تحویل اعلان ممکن است با محدودیت‌های اندروید تغییر کند");TextView permit=action("فعال‌سازی اعلان‌ها برای مهلت‌ها");permit.setOnClickListener(v->{if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},90);else toast("اعلان‌ها در این نسخه اندروید فعال هستند");});page.addView(permit);section("فهرست‌های قابل تنظیم","موارد دلخواه خود را اضافه کنید");TextView cats=action("مدیریت دسته‌بندی پرونده‌ها"),subjects=action("مدیریت موضوعات پرونده"),actions=action("مدیریت انواع اقدام و گردش کار"),sms=action("مدیریت متن‌ها و عنوان‌های پیامک");cats.setOnClickListener(v->manageSimpleList("دسته‌بندی پرونده‌ها","categories",defaultCategories()));subjects.setOnClickListener(v->manageSimpleList("موضوعات پرونده","subjects",defaultSubjects()));actions.setOnClickListener(v->manageSimpleList("انواع اقدام پرونده","work_actions",defaultActions()));sms.setOnClickListener(v->manageSmsTemplates());page.addView(cats);page.addView(subjects);page.addView(actions);page.addView(sms);page.addView(info("مهلت قضایی","مدت و آخرین روز هر مهلت را مطابق پرونده بررسی و خودتان ثبت کنید. پیشنهاد تاریخ به تنهایی مبنای تصمیم قضایی نیست."));page.addView(info("حریم خصوصی","اطلاعات روی همین گوشی ذخیره می‌شود. برای پیامک، متن در برنامه پیامک گوشی باز می‌شود و ارسال نهایی فقط با تأیید شما انجام خواهد شد."));}

  void manageSimpleList(String title,String key,String defaults){LinearLayout f=form();EditText current=area("هر مورد در یک خط");current.setMinLines(10);current.setText(prefs.getString(key,defaults));f.addView(current);new AlertDialog.Builder(this).setTitle(title).setView(scroll(f)).setNegativeButton("انصراف",null).setPositiveButton("ذخیره",(d,w)->{String clean=cleanLines(current.getText().toString());if(blank(clean)){toast("فهرست نمی‌تواند خالی باشد");return;}prefs.edit().putString(key,clean).apply();toast("فهرست ذخیره شد");}).show();}
  void manageSmsTemplates(){LinearLayout f=form();EditText title=input("عنوان پیامک"),body=area("متن پیامک");TextView add=action("افزودن به فهرست");LinearLayout saved=col();Runnable draw=()->{saved.removeAllViews();String[] rows=smsRows();for(String row:rows){String[] p=row.split("§",2);saved.addView(info(p[0],p.length>1?p[1]:""));}};add.setOnClickListener(v->{if(blank(title.getText().toString())||blank(body.getText().toString())){toast("عنوان و متن را وارد کنید");return;}String old=prefs.getString("sms_templates",defaultSms());prefs.edit().putString("sms_templates",old+"\n"+title.getText().toString().replace("§","")+"§"+body.getText().toString().replace("§","")).apply();title.setText("");body.setText("");draw.run();});f.addView(title);f.addView(body);f.addView(add);f.addView(saved);draw.run();new AlertDialog.Builder(this).setTitle("الگوهای پیامک").setView(scroll(f)).setNegativeButton("بستن",null).setPositiveButton("بازنشانی پیش‌فرض",(d,w)->prefs.edit().putString("sms_templates",defaultSms()).apply()).show();}
  void chooseSms(String phone,String client){if(blank(phone)){toast("برای این موکل شماره تلفن ثبت نشده است");return;}String[] rows=smsRows(),titles=new String[rows.length];for(int i=0;i<rows.length;i++)titles[i]=rows[i].split("§",2)[0];new AlertDialog.Builder(this).setTitle("انتخاب عنوان پیامک").setItems(titles,(d,n)->{String[] p=rows[n].split("§",2);String body=(p.length>1?p[1]:"").replace("{موکل}",safe(client));Intent i=new Intent(Intent.ACTION_SENDTO,Uri.parse("smsto:"+Uri.encode(phone)));i.putExtra("sms_body",body);try{startActivity(i);}catch(Exception e){toast("برنامه پیامک در گوشی پیدا نشد");}}).show();}

  String html(String heading,String body){String logo=imageData(prefs.getString("logo",null)),img=blank(logo)?"":"<img src='"+logo+"' style='width:72px;height:72px;object-fit:contain'>",name=esc(prefs.getString("name","")),level=esc(prefs.getString("lawyer_level","وکیل")),license=esc(prefs.getString("license","")),center=esc(prefs.getString("center","")),phone=esc(prefs.getString("phone","")),address=esc(prefs.getString("address","")),web=esc(prefs.getString("website",""));return "<!doctype html><html dir='rtl'><head><meta charset='utf-8'><style>@page{size:A4;margin:18mm}body{font-family:sans-serif;direction:rtl;color:#182236;line-height:2}.head{display:flex;align-items:center;border-bottom:3px solid #152446;padding-bottom:12px}.brand{flex:1}h1,h2,p{margin:0}.meta{font-size:12px;color:#566176}.body{white-space:pre-wrap;margin-top:28px;font-size:14px}.foot{margin-top:50px;border-top:1px solid #bbb;padding-top:8px;font-size:11px}</style></head><body><div class='head'>"+img+"<div class='brand'><h1>دفتر وکالت "+name+"</h1><p>"+level+" · "+center+"</p><p class='meta'>شماره پروانه: "+license+"</p></div></div><h2 style='text-align:center;margin-top:24px'>"+esc(heading)+"</h2><div class='body'>"+esc(body)+"</div><div class='foot'>تلفن: "+phone+" | نشانی: "+address+" | "+web+"</div></body></html>";}
  void print(String name,String html){printView=new WebView(this);printView.getSettings().setDefaultTextEncodingName("UTF-8");printView.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String u){PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);pm.print(name,v.createPrintDocumentAdapter(name),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).build());}});printView.loadDataWithBaseURL(null,html,"text/html","UTF-8",null);}
  String imageData(String value){if(blank(value))return "";try(InputStream in=getContentResolver().openInputStream(Uri.parse(value));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return "data:image/jpeg;base64,"+Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP);}catch(Exception e){return "";}}

