  Spinner spinner(String[] a){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a));s.setLayoutParams(lp(-1,dp(54)));return s;} ImageView image(String uri){ImageView i=new ImageView(this);i.setScaleType(ImageView.ScaleType.CENTER_CROP);i.setPadding(dp(4),dp(4),dp(4),dp(4));i.setBackground(round(Color.WHITE,14));if(!blank(uri))try{i.setImageURI(Uri.parse(uri));}catch(Exception ignored){}return i;}
  LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);return l;} LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);return l;} TextView txt(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z*fontScale);t.setTextColor(c);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);t.setTextDirection(View.TEXT_DIRECTION_RTL);return t;}
  GradientDrawable round(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c==Color.WHITE?CARD:c);g.setCornerRadius(dp(r));return g;} LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w,h);} LinearLayout.LayoutParams weight(){return new LinearLayout.LayoutParams(0,-2,1);} void margin(View v,int l,int t,int r,int b){LinearLayout.LayoutParams p=v.getLayoutParams() instanceof LinearLayout.LayoutParams?(LinearLayout.LayoutParams)v.getLayoutParams():new LinearLayout.LayoutParams(-1,-2);p.setMargins(dp(l),dp(t),dp(r),dp(b));v.setLayoutParams(p);} int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
  boolean blank(String s){return s==null||s.trim().isEmpty();} String safe(String s){return blank(s)?"ثبت نشده":s;} long parseMoney(String s){try{return Long.parseLong(s.replace(",","").replace("٬","").trim());}catch(Exception e){return 0;}} String money(long v){return String.format(Locale.US,"%,d ریال",v);} String ymd(int y,int m,int d){return String.format(Locale.US,"%04d/%02d/%02d",y,m,d);} void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();} String esc(String s){if(s==null)return "";return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\n","<br>");}
  String defaultCategories(){return "کیفری\nحقوقی\nانقلاب\nخانواده\nدیوان عدالت اداری\nنظامی\nسایر";} String defaultSubjects(){return "مطالبه وجه\nالزام به ایفای تعهد\nاعتراض به رأی\nاختلاف خانوادگی\nشکایت اداری\nدفاع کیفری\nاختلاف قراردادی\nسایر";} String defaultActions(){return "مطالعه پرونده\nمراجعه به شعبه\nگفتگو با قاضی\nگفتگو با مدیر دفتر\nپیگیری پرونده\nارسال لایحه\nجلسه با موکل\nحضور در جلسه رسیدگی\nمراجعه برای کارشناسی\nسایر";} String defaultSms(){return "یادآوری جلسه§{موکل} گرامی، زمان جلسه شما یادآوری می‌شود. لطفاً با دفتر هماهنگ فرمایید.\nاطلاع پرونده§{موکل} گرامی، درباره پرونده شما به‌روزرسانی ثبت شده است. لطفاً با دفتر تماس بگیرید.\nیادآوری پرداخت§{موکل} گرامی، لطفاً درباره وضعیت مالی پرونده با دفتر هماهنگ فرمایید.";}
  String[] categoryList(){return lines(prefs.getString("categories",defaultCategories()));} String[] subjectList(){return lines(prefs.getString("subjects",defaultSubjects()));} String[] workActionList(){return lines(prefs.getString("work_actions",defaultActions()));} String[] smsRows(){return lines(prefs.getString("sms_templates",defaultSms()));} String[] withAll(String[] a){String[] b=new String[a.length+1];b[0]="همه";System.arraycopy(a,0,b,1,a.length);return b;} String[] lines(String s){String clean=cleanLines(s);return blank(clean)?new String[]{"سایر"}:clean.split("\n");} String cleanLines(String s){if(s==null)return "";StringBuilder b=new StringBuilder();for(String x:s.split("\\r?\\n")){x=x.trim();if(!x.isEmpty()){if(b.length()>0)b.append('\n');b.append(x);}}return b.toString();}
  String casesText(List<OfficeDb.CaseRecord> list){StringBuilder b=new StringBuilder();for(OfficeDb.CaseRecord c:list)b.append(c.title).append("\nشماره: ").append(safe(c.caseNumber)).append(" | موکل: ").append(safe(c.clientName)).append("\nوضعیت: ").append("active".equals(c.status)?"جاری":"مختومه").append(" | دسته: ").append(safe(c.category)).append(" | موضوع: ").append(safe(c.subject)).append("\nمرجع: ").append(safe(c.authorityType)).append("، ").append(safe(c.province)).append("، ").append(safe(c.judicialCity)).append("\n\n");return b.toString();}
