  String workLogsText(List<OfficeDb.WorkLogRecord> list){StringBuilder b=new StringBuilder();for(OfficeDb.WorkLogRecord x:list)b.append(safe(x.date)).append(" | ").append(safe(x.type)).append("\nپرونده: ").append(safe(x.caseTitle)).append(" | موکل: ").append(safe(x.clientName)).append("\n").append(safe(x.description)).append("\n\n");return b.toString();}
  String strongHash(String pass){try{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);PBEKeySpec spec=new PBEKeySpec(pass.toCharArray(),salt,150000,256);byte[] digest=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();spec.clearPassword();return "pbkdf2$"+Base64.encodeToString(salt,Base64.NO_WRAP)+"$"+Base64.encodeToString(digest,Base64.NO_WRAP);}catch(Exception e){throw new IllegalStateException("ذخیره رمز امن ممکن نیست",e);}}
  boolean verifyPassword(String pass){String saved=prefs.getString("password_hash","");try{if(saved.startsWith("pbkdf2$")){String[] parts=saved.split("\\$");if(parts.length!=3)return false;byte[] salt=Base64.decode(parts[1],Base64.NO_WRAP),expected=Base64.decode(parts[2],Base64.NO_WRAP);PBEKeySpec spec=new PBEKeySpec(pass.toCharArray(),salt,150000,expected.length*8);byte[] actual=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();spec.clearPassword();return MessageDigest.isEqual(actual,expected);}if(!saved.isEmpty()&&MessageDigest.isEqual(hash(pass).getBytes("UTF-8"),saved.getBytes("UTF-8"))){prefs.edit().putString("password_hash",strongHash(pass)).apply();return true;}}catch(Exception ignored){}return false;}
  String hash(String s){try{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(s.getBytes("UTF-8"));StringBuilder b=new StringBuilder();for(byte x:bytes)b.append(String.format(Locale.US,"%02x",x));return b.toString();}catch(Exception e){throw new IllegalStateException("تأیید رمز ممکن نیست",e);}}
